/* text.js — the ONE live-text renderer for muskan-shourya.
 *
 * Every readable string on this invitation is HTML text, typeset over the artwork from
 * data/textspec.json (generated by tools/extract_text.py from the client's PSDs). No
 * scene may hard-code a name, a date, a venue or a dress code: the spec is the only
 * source of copy, and the only source of geometry.
 *
 * ---------------------------------------------------------------------------
 * API — two calls, mirroring the kit's lifecycle contract.
 *
 *   import * as text from "../fx/text.js";
 *
 *   enter(ctx) { text.mount(ctx); }    // build (or rebuild) this scene's copy, armed
 *   idle(ctx)  { text.reveal(ctx); }   // play the cascade, once the entry cascade is done
 *
 * mount() is safe to call on every entry — it clears and rebuilds, so a re-visit
 * replays the reveal from scratch. Both are no-ops if ctx is no longer the live scene.
 * ctx.signal drives HYGIENE, not removal: leaving a scene cancels every animation,
 * restores every split run and drops every will-change, so document.getAnimations()
 * returns to zero and the resting DOM is byte-identical to the un-animated render —
 * but the copy STAYS RENDERED, so the transition carries it off the page with the
 * artwork it belongs to. See retire().
 *
 * ---------------------------------------------------------------------------
 * TYPESETTING MODEL (why the DOM looks the way it does)
 *
 *   block  -> one absolutely positioned box on the spec's ink bbox. The box exists to
 *             give the reveal a sane transform-origin (its own optical centre); the
 *             copy inside is positioned independently of it.
 *   line   -> absolutely positioned, one per entry in `lines`, placed so its BASELINE
 *             sits on the spec baseline. Photoshop leads a line by ITS OWN
 *             lineHeightPx, so baseline[n] = baseline[n-1] + lineHeightPx[n] — which is
 *             why lines are placed individually and never flowed.
 *             Horizontally the line anchors on anchor.x (the PSD type origin), NOT on
 *             the bbox centre: the script faces overhang asymmetrically and bbox
 *             centres are off by up to 18px on those.
 *   run    -> one <span> per spec run. Mixed sizes, colours, tracking, features and
 *             superscripts all live at this level.
 *
 * BASELINE PLACEMENT: a line box's baseline offset depends on the resolved font's
 * vertical metrics, which no stylesheet can express portably. So each line is measured
 * ONCE against a zero-height inline-block probe (whose own baseline is its top edge)
 * and the offset is cached per slug/block/line for the life of the page. The measured
 * offset is divided by the container's live scale, so it is stored in design px and a
 * resize (or a mid-transition scale) can never corrupt it.
 *
 * SUPERSCRIPTS: typeset at run.renderSizePx and raised run.renderRaisePx with
 * vertical-align. Never CSS `super` on top — that would scale the glyph twice.
 *
 * FAUX BOLD: -webkit-text-stroke thickens the outline; it does NOT widen the advance.
 * The spec measured the missing advance at 0.027em off qa/textref, so both are applied.
 *
 * OUTLINE: block.outline is the layer's own Photoshop Stroke effect — weight the
 * designer drew, not a calibration. It is the other half of "why is this line heavier
 * than the same face elsewhere", and it is why the cover's couple names are heavier
 * than the names scene's. Applied as -webkit-text-stroke at the spec's width (already
 * doubled for Photoshop's OUTSIDE position, already in design px) and NOT paired with
 * any tracking: a stroke does not move an advance, and measured against the client's
 * flatten the advance holds to 0.00%.
 *
 * SCRIPT REVEAL: Rungkut and Hello Bride reveal grapheme by grapheme in writing order.
 * The graphemes are plain INLINE spans animating opacity + blur only — measured, that
 * holds every script string's advance to <=0.17px, while display:inline-block breaks
 * Hello Bride's ligatures ("Wedding Ceremony" renders 7.7px / 1.0% wide). The intact
 * text node is restored the moment the cascade lands, so the resting render is exactly
 * the un-split one.
 */

const SPEC_URL = "data/textspec.json?v=57";

const DESIGN_W = 1080;

/* Mirrors of the css/fx/text.css tokens, needed here only to know when the cascade has
   LANDED. Keep the two in step: --ms-block-ms / --ms-letter-step / --ms-letter-ms. */
const BLOCK_STAGGER = 72; /* ms between blocks, in reading order */
const BLOCK_MS = 780;
const LETTER_STEP = 38;
const LETTER_MS = 560;
const REDUCED_MS = 420;

/* Photoshop's synthetic bold widens every advance by this much on top of the outline
   thickening. Measured in data/textspec.json `fauxBoldEmEstimate`. */
const FAUX_TRACK_EM = 0.027;

/* the two script faces: display names + event titles. Everything else is body copy. */
const SCRIPT_FAMILIES = { Rungkut: true, "Hello Bride": true };

const STACK = {
  Rungkut: "var(--font-display)",
  "Cormorant Garamond": "var(--font-body)",
  "Hello Bride": "var(--font-script)"
};

/* exactly one h1 in the document — the cover's couple names. Every other scene's
   display title is an h2; body copy is a <p>. */
const H1 = "cover/couple-names";

/* ------------------------------------------------------------------ loading */

/* Both start at import time, in parallel with the engine's own boot fetches, so the
   first scene has its copy ready before the entry cascade ends. */

const specPromise = (function () {
  if (typeof fetch !== "function") return Promise.resolve(null);
  return fetch(SPEC_URL, { cache: "no-cache" })
    .then(function (r) {
      return r.ok ? r.json() : null;
    })
    .catch(function () {
      return null; /* missing spec must never wedge the engine — scenes render art-only */
    });
})();

/* document.fonts.ready alone resolves early when nothing has asked for a face yet, so
   demand every face up front and only then wait on it. Measuring in a fallback face
   would poison the baseline cache for the life of the page. */
const fontsPromise = (function () {
  if (typeof document === "undefined" || !document.fonts) return Promise.resolve();
  const specs = [
    "400 100px 'Rungkut'",
    "400 100px 'Cormorant Garamond'",
    "600 100px 'Cormorant Garamond'",
    "400 100px 'Hello Bride'",
    "400 100px 'Tiro Devanagari Sanskrit'"
  ];
  return Promise.all(
    specs.map(function (s) {
      return document.fonts.load(s).catch(function () {});
    })
  ).then(function () {
    return document.fonts.ready;
  });
})();

const ready = Promise.all([specPromise, fontsPromise]).then(function (r) {
  return r[0];
});

/* slug -> live record. One scene is ever live, but keying by slug keeps a stale
   record from a scene the guest swiped away from out of the live one's way. */
const records = new Map();

/* "slug|blockId|lineIndex" -> baseline offset in DESIGN px. Font metrics do not change
   for the life of the page, so this is measured once and reused on every re-entry. */
const baselineCache = new Map();

/* --------------------------------------------------------------- utilities */

function reducedMotion(ctx) {
  if (ctx && typeof ctx.reducedMotion === "boolean") return ctx.reducedMotion;
  return !!(typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches);
}

const segmenter =
  typeof Intl !== "undefined" && typeof Intl.Segmenter === "function"
    ? new Intl.Segmenter(undefined, { granularity: "grapheme" })
    : null;

function graphemes(str) {
  if (!segmenter) return Array.from(str);
  const out = [];
  const it = segmenter.segment(str);
  for (const seg of it) out.push(seg.segment);
  return out;
}

function stackFor(family) {
  return STACK[family] || "'" + family + "', Georgia, 'Times New Roman', serif";
}

function px(n) {
  return (Math.round(n * 100) / 100) + "px";
}

/* --------------------------------------------------------------- container */

/** The .scene-text overlay. Built here, not by js/stage.js: data/template.json no
 *  longer carries text slots, so the engine has nothing to build one from. */
function ensureBox(ctx) {
  let box = ctx.frame.querySelector(".scene-text");
  if (!box) {
    box = document.createElement("div");
    box.className = "scene-text ms-text";
    box.setAttribute("data-scene-text", ctx.slug);
    ctx.frame.appendChild(box);
  }
  box.classList.add("ms-text");
  return box;
}

/* ------------------------------------------------------------------- build */

function runSpan(block, run) {
  const s = document.createElement("span");
  s.className = "ms-r";
  s.textContent = run.text;

  const size = run.renderSizePx != null ? run.renderSizePx : run.sizePx;
  const st = s.style;
  st.fontFamily = stackFor(run.fontFamily || block.fontFamily);
  st.fontWeight = String(run.fontWeight || block.fontWeight || 400);
  st.fontSize = px(size);
  st.color = run.color || block.color;

  /* letterSpacingPx is the spec's own tracking for this run, already resolved against
     the run's size. Faux bold adds the advance the outline stroke cannot. */
  let ls = run.letterSpacingPx || 0;
  if (run.fauxBold) {
    ls += FAUX_TRACK_EM * size;
    s.classList.add("ms-r--fb");
    /* the script faces take a lighter synthetic stroke than Cormorant — the two are
       measured separately against qa/textref, see css/fx/text.css --ms-faux-stroke* */
    if (SCRIPT_FAMILIES[run.fontFamily || block.fontFamily]) s.classList.add("ms-r--script");
  }
  if (ls) st.letterSpacing = px(ls);

  /* PSD STROKE LAYER EFFECT. The designer's own outline on the layer — the cover's
     couple names carry one, which is what makes that line heavier than the same face
     elsewhere. Unlike synthetic bold it is authored data, not a calibration: the width
     arrives from the spec already doubled for Photoshop's OUTSIDE position and already
     in design px, so it is written straight out. It thickens the outline only, so no
     tracking rides along — and measured, the advance holds to 0.00%.
     css/fx/text.css adds --ms-outline to the synthetic-bold width; no layer in this
     spec is both, but Photoshop would stack them, so the stylesheet does too. */
  const outline = block.outline;
  if (outline && outline.webkitTextStrokePx > 0) {
    s.classList.add("ms-r--outline");
    st.setProperty("--ms-outline", px(outline.webkitTextStrokePx));
    st.setProperty("--ms-outline-color", outline.color || "currentColor");
  }

  if (run.renderRaisePx) st.verticalAlign = px(run.renderRaisePx);

  if (run.textTransform && run.textTransform !== "none") st.textTransform = run.textTransform;

  /* "case" is what gives Cormorant its tall lining figures; without it "NOVEMBER, 2026"
     drops to short old-style ones. Photoshop's Ligatures checkbox rides along here too,
     because font-feature-settings overrides font-variant-ligatures when both are set. */
  const feats = (run.fontFeatures || []).map(function (f) {
    return '"' + f + '" 1';
  });

  /* LINING FIGURES. Cormorant's default figures are old-style: 6 and 8 ascend, 0/1/2
     sit at x-height, 3/4/5/7/9 descend. Every number in the client artwork is lining.
     The spec carries "case" (Photoshop's All Caps) on the date runs, which happens to
     swap in the lining set — but the time runs are not All Caps, so they carry no
     feature at all and rendered "6:00" as a tall 6 with two x-height zeros against a
     reference that is uniformly tall.
     TODO(production): this belongs in the spec. tools/extract_text.py models the
     digit runs' distinct Photoshop style only as `ligatures:false` — the figure style
     that actually distinguishes them is not extracted. Re-run the extractor with a
     figure-style field and this clause can go. */
  if (/[0-9]/.test(run.text)) feats.push('"lnum" 1');
  if (run.ligatures === false) {
    if (feats.length) {
      feats.push('"liga" 0', '"clig" 0');
    } else {
      s.classList.add("ms-r--noliga");
    }
  }
  if (feats.length) st.fontFeatureSettings = feats.join(", ");

  /* CSS tracks AFTER the last character too; Photoshop's centring does not count that
     trailing sliver. Left in, every tracked centred line drifts half a track to the
     left — measured at -3.5px on the cover's date blocks (0.18em) and -3.0px on
     NOVEMBER, 2026 (0.06em). The caller pulls it back off the last run of the line. */
  s.__ls = ls;
  return s;
}

function tagFor(slug, block) {
  const script = !!SCRIPT_FAMILIES[block.fontFamily];
  if (!script || block.id === "ampersand") return "p";
  return (slug + "/" + block.id) === H1 ? "h1" : "h2";
}

function buildBlock(rec, block, order) {
  const slug = rec.slug;
  const bbox = block.bbox;
  const x0 = bbox[0];
  const y0 = bbox[1];
  const script = !!SCRIPT_FAMILIES[block.fontFamily];

  const el = document.createElement(tagFor(slug, block));
  el.className = "ms-b" + (script ? " ms-b--script" : "");
  el.setAttribute("data-block", block.id);
  if (block.lang) el.setAttribute("lang", block.lang);
  el.style.left = px(x0);
  el.style.top = px(y0);
  el.style.width = px(bbox[2] - x0);
  el.style.height = px(bbox[3] - y0);
  el.style.setProperty("--d", order * BLOCK_STAGGER + "ms");

  /* Script blocks are split grapheme-by-grapheme while they reveal. A stable
     aria-label keeps the announcement whole (and in the designer's source casing)
     whatever the children happen to be mid-cascade. */
  if (script) el.setAttribute("aria-label", (block.lines || []).join(" "));

  const align = block.textAlign || "center";
  const runsByLine = [];
  (block.runs || []).forEach(function (run) {
    const i = run.line || 0;
    (runsByLine[i] || (runsByLine[i] = [])).push(run);
  });

  /* baseline[n] = baseline[n-1] + lineHeightPx[n] — Photoshop leads a line by its own
     leading, which is why per-line lineHeightPx is read and not the block's. */
  const styles = block.lineStyles || [];
  let baseline = block.anchor.baselineY;
  const lines = [];

  (block.lines || []).forEach(function (_text, i) {
    if (i > 0) {
      const ls = styles[i];
      baseline += ls && ls.lineHeightPx != null ? ls.lineHeightPx : block.lineHeightPx;
    }
    const line = document.createElement("span");
    line.className =
      "ms-ln" + (align === "center" ? " ms-ln--center" : align === "right" ? " ms-ln--right" : "");
    line.style.left = px(block.anchor.x - x0);
    const runs = runsByLine[i] || [];
    let tail = null;
    runs.forEach(function (run) {
      tail = runSpan(block, run);
      line.appendChild(tail);
    });
    if (tail && tail.__ls) tail.style.marginRight = px(-tail.__ls);
    el.appendChild(line);
    /* `top` is block-local: the lines live inside the bbox box, so the spec's absolute
       baselineY has to come back to the block's own origin. */
    lines.push({ el: line, top: baseline - y0, key: slug + "|" + block.id + "|" + i });
  });

  return { el: el, lines: lines, script: script, block: block };
}

/**
 * Place every line by its baseline.
 *
 * Cached lines are written straight out. Uncached ones get a zero-height probe whose
 * own baseline is its top edge; one read pass measures them all, one write pass places
 * them, and the probes are dropped again. The container's live width gives the exact
 * design->screen scale, including any transform an ancestor happens to be running, so
 * a measurement taken mid-transition is still stored in clean design px.
 */
function placeLines(rec, built) {
  const pending = [];
  built.forEach(function (b) {
    b.lines.forEach(function (line) {
      if (baselineCache.has(line.key)) return;
      const probe = document.createElement("i");
      probe.className = "ms-bl";
      line.el.appendChild(probe);
      pending.push({ line: line, probe: probe });
    });
  });

  if (pending.length) {
    const boxRect = rec.box.getBoundingClientRect();
    const scale = boxRect.width / DESIGN_W;
    if (!(scale > 0)) {
      /* the scene is not painting yet (display:none) — nothing measurable, and a
         guessed scale would poison the cache for the life of the page. Drop the
         probes and try again on the next frame. */
      pending.forEach(function (p) {
        p.probe.parentNode.removeChild(p.probe);
      });
      return false;
    }
    pending.forEach(function (p) {
      const lr = p.line.el.getBoundingClientRect();
      const pr = p.probe.getBoundingClientRect();
      baselineCache.set(p.line.key, (pr.top - lr.top) / scale);
    });
    pending.forEach(function (p) {
      p.probe.parentNode.removeChild(p.probe);
    });
  }

  built.forEach(function (b) {
    b.lines.forEach(function (line) {
      line.el.style.top = px(line.top - baselineCache.get(line.key));
    });
  });
  return true;
}

function build(rec, spec) {
  const scene = spec && spec.scenes ? spec.scenes[rec.slug] : null;
  const blocks = (scene && Array.isArray(scene.blocks) ? scene.blocks : []).filter(function (block) {
    return block.visible !== false;
  });
  if (!blocks.length) return false;

  const frag = document.createDocumentFragment();
  const built = blocks.map(function (block, i) {
    const b = buildBlock(rec, block, i);
    frag.appendChild(b.el);
    return b;
  });
  rec.box.appendChild(frag);
  rec.built = built;
  if (!placeLines(rec, built)) {
    requestAnimationFrame(function () {
      if (records.get(rec.slug) === rec) placeLines(rec, built);
    });
  }
  return true;
}

/* ------------------------------------------------------------------ reveal */

/** Split every run of a script block into inline graphemes, numbered in writing order.
 *  Returns the undo list that restores the intact text nodes. */
function splitScript(built) {
  const restore = [];
  let i = 0;
  built.lines.forEach(function (line) {
    Array.prototype.forEach.call(line.el.querySelectorAll(".ms-r"), function (run) {
      const text = run.textContent;
      restore.push({ run: run, text: text });
      run.textContent = "";
      graphemes(text).forEach(function (g) {
        const s = document.createElement("span");
        s.className = "ms-g";
        s.style.setProperty("--i", String(i));
        s.textContent = g;
        run.appendChild(s);
        i += 1;
      });
    });
  });
  return { restore: restore, count: i };
}

function play(rec) {
  if (rec.played || !rec.built) return;
  rec.played = true;

  const reduce = reducedMotion(rec.ctx);
  let last = 0;

  rec.built.forEach(function (b, i) {
    const at = i * BLOCK_STAGGER;
    let ms = at + BLOCK_MS;
    if (b.script && !reduce) {
      const split = splitScript(b);
      rec.restore = rec.restore.concat(split.restore);
      ms = at + Math.max(0, split.count - 1) * LETTER_STEP + LETTER_MS;
    }
    if (ms > last) last = ms;
  });

  rec.box.classList.add("is-revealing");

  /* One timer, not an animationend race: the cascade's tail is a grapheme deep inside a
     run, and a dropped frame on a hidden tab must not leave the copy armed. */
  rec.settle = setTimeout(function () {
    settle(rec);
  }, (reduce ? REDUCED_MS : last) + 90);
}

/** Land the cascade: spec geometry, intact text, no animations, no will-change.
 *  Called by the settle timer at the end of the cascade, and by retire() — from which
 *  it doubles as the floor for copy that never got to reveal at all. */
function settle(rec) {
  clearTimeout(rec.settle);
  rec.settle = 0;
  if (!rec.box) return;
  restoreRuns(rec);
  rec.box.classList.add("is-revealed");
  rec.box.classList.remove("is-revealing");
  cancelAnimations(rec.box);
}

function restoreRuns(rec) {
  if (!rec.restore.length) return;
  rec.restore.forEach(function (r) {
    r.run.textContent = r.text;
  });
  rec.restore = [];
}

function cancelAnimations(box) {
  if (!box || typeof box.getAnimations !== "function") return;
  box.getAnimations({ subtree: true }).forEach(function (a) {
    try {
      a.cancel();
    } catch (e) {
      /* a cancelled animation must never take the scene down with it */
    }
  });
}

/**
 * The scene is leaving. HYGIENE ONLY — the copy stays on the page.
 *
 * js/stage.js aborts ctx.signal at the START of the transition (`go()` calls
 * activeCtx._abort() before the driver runs), a full driver duration — 900ms of
 * breeze, 1600ms of balloon — before the outgoing scene is unmounted. Removing the
 * copy here, which is what "clean up on abort" used to mean, blinked every scene's
 * invitation text out on the first frame of the breeze / dolly / balloon / mirror /
 * glow / petal sweeps: the artwork was carried off a page whose words had already
 * gone. The words are part of the page. They leave with it.
 *
 * So land the cascade wherever it stands — intact text nodes, spec geometry, zero
 * animations, no will-change — and leave the result in the DOM. The engine hides the
 * whole scene on unmount, so stale-but-correct copy is never seen again, and the next
 * mount() empties the box and rebuilds it armed in the same task that re-shows the
 * scene, so no frame is ever painted holding the previous visit's revealed text.
 *
 * settle() is also the reveal FLOOR. reveal() is called from idle(); a guest who
 * advances inside the ~600ms before idle() first fires (only reachable on the opening
 * scene, whose module registers after boot) leaves before it ever runs, and that
 * visit's copy would otherwise ride out still armed and invisible. It lands visible.
 */
function retire(rec) {
  settle(rec);
  if (records.get(rec.slug) === rec) records.delete(rec.slug);
}

/* --------------------------------------------------------------- public API */

/**
 * Build this scene's copy, armed and invisible. Call from enter() — it rebuilds on
 * every entry, so the reveal replays on a re-visit.
 * @param {object} ctx the scene ctx handed to enter()
 */
export function mount(ctx) {
  if (!ctx || !ctx.frame) return null;
  const slug = ctx.slug;

  const prev = records.get(slug);
  if (prev) retire(prev);

  const box = ensureBox(ctx);
  box.classList.remove("is-revealing", "is-revealed");
  cancelAnimations(box);
  box.textContent = "";

  const rec = {
    slug: slug,
    ctx: ctx,
    box: box,
    built: null,
    restore: [],
    played: false,
    wantReveal: false,
    settle: 0
  };
  records.set(slug, rec);

  if (ctx.signal) {
    if (ctx.signal.aborted) {
      retire(rec);
      return rec;
    }
    ctx.signal.addEventListener(
      "abort",
      function () {
        retire(rec);
      },
      { once: true }
    );
  }

  ready.then(function (spec) {
    if (records.get(slug) !== rec) return;
    if (ctx.signal && ctx.signal.aborted) return;
    if (!build(rec, spec)) return;
    if (rec.wantReveal) play(rec);
  });

  return rec;
}

/**
 * Play the reading-order cascade. Call from idle(), after the engine's entry cascade
 * has handed `transform` back. Safe to call before mount() has finished building.
 * @param {object} ctx the scene ctx handed to idle()
 */
export function reveal(ctx) {
  const rec = ctx ? records.get(ctx.slug) : null;
  if (!rec || rec.ctx !== ctx) return;
  if (rec.built) play(rec);
  else rec.wantReveal = true;
}

/** QA hook: resolves once the spec and all four faces are in. */
export function whenReady() {
  return ready;
}
